package settlement

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// canonical-vectors.json is generated by scripts/gen-canonical-vectors.py from the
// PYTHON implementation (the side that actually signs on a worker). Both the Go and
// Python implementations assert these bytes, so a drift on either side turns its own
// test red.
//
// Loaded from a normal file (not a _test.go one) so the gateway package's mirror test
// can read the same vectors: the signing payload is implemented in internal/gateway,
// the leaf in internal/settlement, and both must agree with one fixture.

// CanonicalVectorFile is the fixture filename inside a package's testdata directory.
const CanonicalVectorFile = "canonical-vectors.json"

type canonicalVectors struct {
	Payloads []struct {
		Name    string          `json:"name"`
		Shape   string          `json:"shape"`
		Inputs  json.RawMessage `json:"inputs"`
		Payload string          `json:"payload"`
	} `json:"payloads"`
	Leaves []struct {
		Name   string          `json:"name"`
		Shape  string          `json:"shape"`
		Inputs json.RawMessage `json:"inputs"`
		Leaf   string          `json:"leaf"`
	} `json:"leaves"`
	BillableSeconds []struct {
		Duration float64 `json:"duration"`
		Seconds  int     `json:"seconds"`
	} `json:"billable_seconds"`
	CharacterCounts []struct {
		Text  string `json:"text"`
		Count int    `json:"count"`
	} `json:"character_counts"`
}

// LoadCanonicalVectors reads the shared fixture from this package's testdata
// directory, walking nothing: the caller supplies the directory.
func LoadCanonicalVectors(dir string) (canonicalVectors, error) {
	raw, err := os.ReadFile(filepath.Join(dir, CanonicalVectorFile))
	if err != nil {
		return canonicalVectors{}, err
	}
	var v canonicalVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		return canonicalVectors{}, err
	}
	return v, nil
}

// PayloadVector is one signing-payload case: the complete argument set and the exact
// bytes those arguments must produce.
type PayloadVector struct {
	Name    string
	Shape   string
	Inputs  map[string]any
	Payload string
}

// PayloadVectors returns the payload half of the fixture. The gateway package owns the
// Go implementation of that payload, so it consumes these from its own test; the leaf
// half is consumed here.
func PayloadVectors(dir string) ([]PayloadVector, error) {
	v, err := LoadCanonicalVectors(dir)
	if err != nil {
		return nil, err
	}
	out := make([]PayloadVector, 0, len(v.Payloads))
	for _, pv := range v.Payloads {
		var in map[string]any
		if err := json.Unmarshal(pv.Inputs, &in); err != nil {
			return nil, err
		}
		out = append(out, PayloadVector{Name: pv.Name, Shape: pv.Shape, Inputs: in, Payload: pv.Payload})
	}
	return out, nil
}

// LeafVector is one Merkle-leaf case.
type LeafVector struct {
	Name   string
	Shape  string
	Inputs map[string]any
	Leaf   string
}

// LeafVectors returns the leaf half of the fixture.
func LeafVectors(dir string) ([]LeafVector, error) {
	v, err := LoadCanonicalVectors(dir)
	if err != nil {
		return nil, err
	}
	out := make([]LeafVector, 0, len(v.Leaves))
	for _, lv := range v.Leaves {
		var in map[string]any
		if err := json.Unmarshal(lv.Inputs, &in); err != nil {
			return nil, err
		}
		out = append(out, LeafVector{Name: lv.Name, Shape: lv.Shape, Inputs: in, Leaf: lv.Leaf})
	}
	return out, nil
}
